// Layout: two computer containers side by side with a 240px gap for the "copy app" arrow.
// Laptop x 40..360, Server x 600..920, both y 70..400.
// Inside each: App box (w160,h64) at y 156, dependency blocks (w160,h56) at y 236 and y 316, centered at cx 200 / 760.
// "error" label above the server App (y 120). One note centered below (y 424).
const tl = h.timeline();

// Laptop
const laptop = h.container({ x: 40, y: 70, w: 320, h: 330, label: 'Laptop', role: 'neutral' });
const lapApp = h.box({ x: 120, y: 156, w: 160, h: 64, label: 'App', role: 'active' });
const lapPy = h.box({ x: 120, y: 236, w: 160, h: 56, label: 'Python 3.12', role: 'new', size: 'body' });
const lapSsl = h.box({ x: 120, y: 316, w: 160, h: 56, label: 'libssl 3', role: 'new', size: 'body' });

// Server
const server = h.container({ x: 600, y: 70, w: 320, h: 330, label: 'Server', role: 'neutral' });
const srvApp = h.box({ x: 680, y: 156, w: 160, h: 64, label: 'App', role: 'active' });
const srvPy = h.box({ x: 680, y: 236, w: 160, h: 56, label: 'Python 3.8', role: 'old', size: 'body' });
const srvSsl = h.box({ x: 680, y: 316, w: 160, h: 56, label: 'no libssl 3', role: 'muted', size: 'body', dashed: true });

const errText = h.text({ x: 760, y: 120, text: 'error', size: 'body', anchor: 'middle', role: 'danger' });

const copy = h.arrow(lapApp, srvApp, { label: 'copy app', role: 'accent' });

const n = h.note({ x: 300, y: 424, w: 360, text: 'Same app, but the server has different dependencies.', role: 'accent' });

// Initially hidden things
gsap.set([srvApp, errText, n], { opacity: 0 });

// 1) Set the scene
h.reveal(tl, [laptop, lapApp, lapPy, lapSsl], 0, { from: 'up', stagger: 0.1 });
h.reveal(tl, [server, srvPy, srvSsl], 0.4, { from: 'up', stagger: 0.1 });

// 2) Copy the app over
h.pulse(tl, lapApp, '>0.4');
h.draw(tl, copy, '>0.2');
h.flow(tl, lapApp, srvApp, '>', { label: 'App', along: copy, role: 'accent' });
h.reveal(tl, srvApp, '>-0.3', { from: 'scale' });

// 3) The server's dependencies differ
h.wait(tl, 0.4);
h.pulse(tl, [srvPy, srvSsl], '>', { times: 1 });
h.recolor(tl, srvSsl, 'danger', '>0.2');

// 4) The one change: the copied app fails
h.recolor(tl, srvApp, 'danger', '>0.4');
h.reveal(tl, errText, '<0.2', { from: 'down' });
h.pulse(tl, srvApp, '>0.1');

h.reveal(tl, n, '>0.5', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: one centered column at cx 480. The 'Image' container spans x 380..580, y 60..410.
// Inside it, App (w160,h64) sits at y 110, followed by Python 3.12 / libssl 3 / config (w160,h56) at y 190, 262 and 334.
// The blocks start scattered left and right (±260px), slide into the column, then the Image outline closes around them.
// Note centered below at y 434.
const tl = h.timeline();

const image = h.container({ x: 380, y: 60, w: 200, h: 350, label: 'Image', role: 'new' });
const app = h.box({ x: 400, y: 110, w: 160, h: 64, label: 'App', role: 'active' });
const py = h.box({ x: 400, y: 190, w: 160, h: 56, label: 'Python 3.12', role: 'new', size: 'body' });
const ssl = h.box({ x: 400, y: 262, w: 160, h: 56, label: 'libssl 3', role: 'new', size: 'body' });
const cfg = h.box({ x: 400, y: 334, w: 160, h: 56, label: 'config', role: 'new', size: 'body' });

const n = h.note({ x: 340, y: 434, w: 280, text: 'no kernel inside', role: 'accent' });

// Initial state: blocks scattered, outline and note hidden
gsap.set(image, { opacity: 0 });
gsap.set(n, { opacity: 0 });
gsap.set(app, { x: -260, opacity: 0 });
gsap.set(py, { x: 260, opacity: 0 });
gsap.set(ssl, { x: -260, opacity: 0 });
gsap.set(cfg, { x: 260, opacity: 0 });

// 1) Set the scene: the app and its loose dependencies
tl.to([app, py, ssl, cfg], { opacity: 1, duration: 0.6, stagger: 0.12 }, 0);
h.pulse(tl, app, '>0.3');

// 2) The one change: everything slides together...
tl.to([app, py, ssl, cfg], { x: 0, duration: 1.2, ease: 'power2.inOut', stagger: 0.08 }, '>0.4');

// ...and the Image outline closes around it
h.reveal(tl, image, '>0.3', { from: 'scale', duration: 0.8 });
h.pulse(tl, image, '>0.2', { times: 1, scale: 1.03 });

// 3) What's not inside
h.reveal(tl, n, '>0.5', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: two columns joined by a labelled arrow.
// Left: Dockerfile code panel x 40..420, y 150 (4 lines, w 380).
// Right: empty dashed "Image" placeholder x 640..880, y 150..270, where the image will appear.
// Gap 420..640 (220px) holds the "docker build" arrow.
// Under the placeholder: a column of four step labels at cx 760, y 294 / 322 / 350 / 378, each revealed in turn.
// One note centered at the bottom (y 430).
const tl = h.timeline();

const file = h.code({
  x: 40, y: 150, w: 380, title: 'Dockerfile',
  lines: [
    'FROM python:3.12',
    'COPY requirements.txt .',
    'RUN pip install -r requirements.txt',
    'COPY . .'
  ]
});

const target = h.box({
  x: 640, y: 150, w: 240, h: 120,
  label: 'Image', sub: 'built here', role: 'muted', dashed: true
});

const build = h.arrow(file, target, { label: 'docker build', role: 'accent' });

const stepTexts = [
  'FROM: start from Python',
  'COPY: add requirements',
  'RUN: install libraries',
  'COPY: add your code'
].map((t, i) => h.text({
  x: 760, y: 294 + i * 28, text: t, size: 'small', anchor: 'middle', role: 'active'
}));

const n = h.note({
  x: 280, y: 430, w: 400,
  text: 'Each instruction is one step of building the image.', role: 'accent'
});

gsap.set([...stepTexts, n], { opacity: 0 });

// 1) Set the scene
h.reveal(tl, file, 0, { from: 'up' });
h.reveal(tl, target, 0.4, { from: 'fade' });

// 2) Start the build
h.draw(tl, build, '>0.3');

// 3) The one change: each line runs in turn
for (let i = 0; i < 4; i++) {
  h.highlightLine(tl, file, i, i === 0 ? '>0.4' : '>');
  h.reveal(tl, stepTexts[i], '<', { from: 'left' });
  if (i > 0) h.dim(tl, stepTexts[i - 1], '<');
  h.wait(tl, 0.7);
}

h.pulse(tl, target, '>');
h.reveal(tl, n, '>0.4', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: two columns joined by a "docker build" arrow (180px gap).
// Left: Dockerfile code panel x 40..420, y 120. "app.py edited" tag below it (y 296). One note below (y 380).
// Right: "Image" container x 600..920, y 70..440. Layer blocks (w180, h56, gap 16) at x 624,
// stacked bottom-up: base y 344, requirements y 272, packages y 200, code y 128.
// "cached" tags sit to the right of the blocks at x 822.
const tl = h.timeline();

const df = h.code({ x: 40, y: 120, w: 380, title: 'Dockerfile', lines: [
  'FROM python:3.12',
  'COPY requirements.txt .',
  'RUN pip install -r requirements.txt',
  'COPY . .'
] });

const image = h.container({ x: 600, y: 70, w: 320, h: 370, label: 'Image', role: 'neutral' });

const bx = 624, bw = 180, bh = 56;
const baseL = h.box({ x: bx, y: 344, w: bw, h: bh, label: 'python:3.12 base', sub: 'base layer', role: 'new', size: 'body' });
const reqL = h.box({ x: bx, y: 272, w: bw, h: bh, label: 'requirements.txt', sub: 'files layer', role: 'new', size: 'body' });
const pkgL = h.box({ x: bx, y: 200, w: bw, h: bh, label: 'installed packages', sub: 'packages layer', role: 'new', size: 'body' });
const codeL = h.box({ x: bx, y: 128, w: bw, h: bh, label: 'your code', sub: 'code layer', role: 'new', size: 'body' });
const layers = [baseL, reqL, pkgL, codeL];

const tagBase = h.text({ x: 822, y: 362, text: 'cached', size: 'small', muted: true, role: 'muted' });
const tagReq = h.text({ x: 822, y: 290, text: 'cached', size: 'small', muted: true, role: 'muted' });
const tagPkg = h.text({ x: 822, y: 218, text: 'cached', size: 'small', muted: true, role: 'muted' });
const tags = [tagBase, tagReq, tagPkg];

const build = h.arrow(df, image, { label: 'docker build', role: 'accent', fromSide: 'right', toSide: 'left' });

const edited = h.text({ x: 230, y: 296, text: 'app.py edited', size: 'body', anchor: 'middle', role: 'active' });

const n = h.note({ x: 40, y: 380, w: 380, text: 'Each layer is read-only: a saved set of file changes.', role: 'accent' });

gsap.set([...layers, ...tags, edited, n], { opacity: 0 });

// 1) Set the scene
h.reveal(tl, [df, image], 0, { from: 'up', stagger: 0.2 });
h.draw(tl, build, '>0.2');

// 2) Build: one layer per instruction, bottom up
for (let i = 0; i < 4; i++) {
  h.highlightLine(tl, df, i, '>0.3');
  h.reveal(tl, layers[i], '<0.1', { from: 'up' });
}

// Layers are saved as read-only
h.recolor(tl, layers, 'neutral', '>0.5');
h.reveal(tl, n, '<', { from: 'up' });

// 3) Code changes, rebuild
h.wait(tl, 0.5);
h.reveal(tl, edited, '>', { from: 'down' });
h.pulse(tl, build, '>0.2');
for (let i = 0; i < 3; i++) {
  h.highlightLine(tl, df, i, '>0.2', { role: 'active' });
  h.reveal(tl, tags[i], '<0.1', { from: 'left', duration: 0.5 });
}

// Only the top layer is remade
h.highlightLine(tl, df, 3, '>0.3');
h.recolor(tl, codeL, 'old', '<0.1');
h.recolor(tl, codeL, 'new', '>0.3');
h.pulse(tl, codeL, '>0.1');

h.wait(tl, 2);
return tl;

// Layout: two columns joined by a wide 'docker run' arrow.
// Left 'Image' container x 80..340, right 'Container' outline x 620..880, both y 60..450.
// Layer blocks are w220 x h56, x +20 inside each column, at y 172, 240, 308, 376 (top to bottom).
// The thin writable layer (h40) sits only in the Container, at y 108, which leaves a 24px gap above the stack.
// Short 'read-only layers' labels sit under each column at y 466.
const tl = h.timeline();

const layerNames = ['your code', 'installed packages', 'requirements.txt', 'python:3.12 base'];
const ys = [172, 240, 308, 376];

// Left: the image (already built in the previous step)
const image = h.container({ x: 80, y: 60, w: 260, h: 390, label: 'Image', role: 'neutral' });
const imgLayers = layerNames.map((name, i) =>
  h.box({ x: 100, y: ys[i], w: 220, h: 56, label: name, role: 'neutral', size: 'body' }));
const roLeft = h.text({ x: 210, y: 466, text: 'read-only layers', size: 'small', anchor: 'middle', muted: true });

// Right: the running container
const cont = h.container({ x: 620, y: 60, w: 260, h: 390, label: 'Container', role: 'active' });
const conLayers = layerNames.map((name, i) =>
  h.box({ x: 640, y: ys[i], w: 220, h: 56, label: name, role: 'neutral', size: 'body' }));
const writable = h.box({ x: 640, y: 108, w: 220, h: 40, label: 'writable layer', role: 'new', size: 'body' });
const roRight = h.text({ x: 750, y: 466, text: 'read-only layers (unchanged)', size: 'small', anchor: 'middle', muted: true });

const run = h.arrow(image, cont, { label: 'docker run', role: 'accent' });

const fileDot = h.token({ x: 820, y: 84, label: 'new file', role: 'accent' });

// Initial state: only the image is visible
gsap.set([cont, ...conLayers, writable, roRight, fileDot], { opacity: 0 });

// 1) Set the scene: the image from the previous step
h.reveal(tl, [image, ...imgLayers], 0, { stagger: 0.08, duration: 0.6 });
h.reveal(tl, roLeft, '>0.1', { duration: 0.5 });

// 2) docker run makes a copy of the stack inside a Container
h.draw(tl, run, '>0.4', { duration: 1 });
h.reveal(tl, cont, '>0.1', { from: 'scale', duration: 0.7 });
h.reveal(tl, [...conLayers].reverse(), '>-0.1', { from: 'left', stagger: 0.12, duration: 0.6 });

// 3) The one change: a thin writable layer is added on top
h.reveal(tl, writable, '>0.5', { from: 'down', duration: 0.8 });
const ring = h.highlight(tl, writable, '>0.2', { role: 'new', pad: 6 });

// 4) A new file goes into the writable layer only
h.reveal(tl, fileDot, '>0.4', { from: 'scale', duration: 0.5 });
h.moveBy(tl, fileDot, { dx: 0, dy: 44 }, '>0.2');
h.hide(tl, fileDot, '>0');
h.pulse(tl, writable, '<0.1', { times: 1, scale: 1.05 });
h.hide(tl, ring, '>0.2');

// The layers below stay unchanged
h.reveal(tl, roRight, '>0.3', { duration: 0.6 });
h.wait(tl, 2);
return tl;

// Layout: three Container outlines in a top row (w240, h140, y 70..210) at x 40, 360, 680 (gap 80).
// Each holds one thin "writable layer" block (w200, h48), role new.
// Image container centred at the bottom: x 360..600, y 290..490, three read-only layers (w200, h40, gap 12).
// "shared layers" label sits to the right of the image (x 624). Dashed muted lines join each container to the image.
const tl = h.timeline();

// --- Image (shared, read-only) ---
const image = h.container({ x: 360, y: 290, w: 240, h: 200, label: 'Image', role: 'neutral' });
const lx = 380, lw = 200, lh = 40;
const codeL = h.box({ x: lx, y: 334, w: lw, h: lh, label: 'your code', role: 'neutral', size: 'body' });
const pkgL = h.box({ x: lx, y: 386, w: lw, h: lh, label: 'packages', role: 'neutral', size: 'body' });
const baseL = h.box({ x: lx, y: 438, w: lw, h: lh, label: 'python base', role: 'neutral', size: 'body' });
const layers = [codeL, pkgL, baseL];
const shared = h.text({ x: 624, y: 392, text: 'shared layers', size: 'body', role: 'accent' });
const ro = h.text({ x: 624, y: 418, text: 'read-only', size: 'small', muted: true, role: 'muted' });

// --- Containers ---
const names = ['Container A', 'Container B', 'Container C'];
const xs = [40, 360, 680];
const conts = [], wls = [], links = [];
for (let i = 0; i < 3; i++) {
  const c = h.container({ x: xs[i], y: 70, w: 240, h: 140, label: names[i], role: 'neutral' });
  const wy = c.inner.y + Math.max(4, (c.inner.h - 48) / 2);
  const wl = h.box({ x: xs[i] + 20, y: wy, w: 200, h: 48, label: 'writable layer', role: 'new', size: 'body' });
  conts.push(c);
  wls.push(wl);
}
for (let i = 0; i < 3; i++) {
  links.push(h.line(conts[i], image, { dashed: true, role: 'muted', fromSide: 'bottom', toSide: 'top' }));
}

gsap.set([image, ...layers, shared, ro, ...conts, ...wls], { opacity: 0 });

// 1) Set the scene: the image from before
h.reveal(tl, [image, ...layers], 0, { from: 'up', stagger: 0.1 });

// 2) Start three containers from it
h.reveal(tl, conts, '>0.3', { from: 'down', stagger: 0.25 });
h.reveal(tl, wls, '>0.1', { from: 'scale', stagger: 0.25 });
for (let i = 0; i < 3; i++) {
  h.draw(tl, links[i], i === 0 ? '>0.3' : '<0.2', { duration: 0.6 });
}

// They all share the same read-only layers
h.reveal(tl, [shared, ro], '>0.2', { from: 'left' });
h.pulse(tl, layers, '<', { times: 1 });
h.pulse(tl, wls, '>0.3', { times: 1 });

// 3) Delete Container C: its writable layer goes with it
h.wait(tl, 0.6);
h.recolor(tl, [conts[2], wls[2]], 'danger', '>');
h.recolor(tl, links[2], 'danger', '<');
h.hide(tl, [conts[2], wls[2], links[2]], '>0.5');

// The image stays untouched
h.pulse(tl, image, '>0.3');

h.wait(tl, 2);
return tl;

// Layout: split canvas. Left half x 40..460 "Virtual Machines", right half x 500..920 "Containers".
// Titles at y 48. Each side has a 'Host' container y 90..470.
// Left: Hypervisor bar x 64..436, y 400 (h48). Two VM boxes (w172, h246) at x 64 and 264, y 130,
//   each holding App (y166), Libraries (y230), Guest Kernel (y294), blocks w148, h48.
// Right: Linux Kernel bar x 524..896, y 400 (h48). Three containers (w108, h166) at x 524/656/788, y 210,
//   labelled 'A', 'B', 'C' (as in step 6), each holding App (y242) and Libraries (y304), blocks w92, h48.
// Note at top of right host (y 124).
const tl = h.timeline();

// Titles
const tVM = h.text({ x: 250, y: 48, text: 'Virtual Machines', size: 'heading', anchor: 'middle' });
const tCT = h.text({ x: 710, y: 48, text: 'Containers', size: 'heading', anchor: 'middle' });

// ---- Left: virtual machines ----
const hostL = h.container({ x: 40, y: 90, w: 420, h: 380, label: 'Host', role: 'neutral' });
const hyper = h.box({ x: 64, y: 400, w: 372, h: 48, label: 'Hypervisor', role: 'muted', size: 'body' });

const vmXs = [64, 264];
const vms = [], vmParts = [], guestKernels = [];
vmXs.forEach((vx, i) => {
  const vm = h.container({ x: vx, y: 130, w: 172, h: 246, label: i === 0 ? 'VM 1' : 'VM 2', role: 'neutral' });
  const app = h.box({ x: vx + 12, y: 166, w: 148, h: 48, label: 'App', role: 'neutral', size: 'body' });
  const lib = h.box({ x: vx + 12, y: 230, w: 148, h: 48, label: 'Libraries', role: 'neutral', size: 'body' });
  const gk = h.box({ x: vx + 12, y: 294, w: 148, h: 48, label: 'Guest Kernel', role: 'neutral', size: 'body' });
  vms.push(vm);
  vmParts.push(app, lib, gk);
  guestKernels.push(gk);
});

// ---- Right: containers ----
const hostR = h.container({ x: 500, y: 90, w: 420, h: 380, label: 'Host', role: 'neutral' });
const kernel = h.box({ x: 524, y: 400, w: 372, h: 48, label: 'Linux Kernel', role: 'muted', size: 'body' });

const cXs = [524, 656, 788];
const names = ['A', 'B', 'C'];
const conts = [], contParts = [];
cXs.forEach((cx, i) => {
  const c = h.container({ x: cx, y: 210, w: 108, h: 166, label: names[i], role: 'neutral' });
  const app = h.box({ x: cx + 8, y: 242, w: 92, h: 48, label: 'App', role: 'neutral', size: 'small' });
  const lib = h.box({ x: cx + 8, y: 304, w: 92, h: 48, label: 'Libraries', role: 'neutral', size: 'small' });
  conts.push(c);
  contParts.push(app, lib);
});

const n = h.note({ x: 524, y: 124, w: 372, text: 'One kernel, shared by every container.', role: 'active' });

gsap.set([n], { opacity: 0 });

// 1) Set the scene: left side, then right side
h.reveal(tl, [tVM, hostL, hyper], 0, { from: 'up', stagger: 0.1 });
h.reveal(tl, [...vms, ...vmParts], '<0.2', { from: 'up', stagger: 0.04 });
h.reveal(tl, [tCT, hostR, kernel], '<0.3', { from: 'up', stagger: 0.1 });
h.reveal(tl, [...conts, ...contParts], '<0.2', { from: 'up', stagger: 0.04 });

// 2) Each VM carries its own kernel
h.recolor(tl, guestKernels, 'old', '>0.5');
h.pulse(tl, guestKernels, '>0.1', { times: 1 });

// 3) The one change: a single shared kernel under all containers
h.recolor(tl, kernel, 'active', '>0.6');
const ring = h.highlight(tl, kernel, '<', { role: 'active', pad: 8 });
h.pulse(tl, conts, '>0.3', { times: 1, scale: 1.04 });
h.reveal(tl, n, '>0.3', { from: 'up' });

h.wait(tl, 2);
return tl;

// Layout: 'Host Computer' container fills canvas (x 40..920, y 60..500).
// 'Linux Kernel' bar along its bottom: x 64..896, y 432..480 (muted).
// Two containers on the kernel: A x 72..412, B x 548..888, y 116..408 (gap 136 for the wall).
// Inside each: 2x2 panels (w134, h52) at columns +24 / +182, rows y 164 and 240,
// then a PID row (h40) at y 316. Dashed namespace wall at x 480, label 'Namespaces' above it (y 96).
const tl = h.timeline();

const host = h.container({ x: 40, y: 60, w: 880, h: 440, label: 'Host Computer', role: 'neutral' });
const kernel = h.box({ x: 64, y: 432, w: 832, h: 48, label: 'Linux Kernel', role: 'muted', size: 'body' });

const names = ['Container A', 'Container B'];
const xs = [72, 548];
const hostnames = ['web-a', 'web-b'];
const conts = [], panels = [], procs = [], pids = [];
for (let i = 0; i < 2; i++) {
  const x0 = xs[i];
  const c = h.container({ x: x0, y: 116, w: 340, h: 292, label: names[i], role: 'neutral' });
  const c1 = x0 + 24, c2 = x0 + 182;
  const files = h.box({ x: c1, y: 164, w: 134, h: 52, label: 'files', sub: '/app', role: 'neutral', size: 'body' });
  const net = h.box({ x: c2, y: 164, w: 134, h: 52, label: 'network', sub: 'eth0', role: 'neutral', size: 'body' });
  const proc = h.box({ x: c1, y: 240, w: 134, h: 52, label: 'processes', role: 'neutral', size: 'body' });
  const hn = h.box({ x: c2, y: 240, w: 134, h: 52, label: 'hostname', sub: hostnames[i], role: 'neutral', size: 'body' });
  const p1 = h.box({ x: c1, y: 316, w: 134, h: 40, label: 'PID 1', role: 'neutral', size: 'small', shape: 'pill' });
  const p2 = h.box({ x: c2, y: 316, w: 134, h: 40, label: 'PID 2', role: 'neutral', size: 'small', shape: 'pill' });
  conts.push(c);
  panels.push([files, net, proc, hn]);
  procs.push(proc);
  pids.push([p1, p2]);
}

const wall = h.line({ x: 480, y: 140 }, { x: 480, y: 404 }, { dashed: true, role: 'muted', width: 4 });
const nsLabel = h.text({ x: 480, y: 96, text: 'Namespaces', size: 'label', anchor: 'middle', role: 'active' });
const look = h.token({ x: 440, y: 190, label: 'look', role: 'accent', r: 14 });

const allPanels = [...panels[0], ...panels[1]];
const allPids = [...pids[0], ...pids[1]];
gsap.set([host, kernel, ...conts, ...allPanels, ...allPids, wall, nsLabel, look], { opacity: 0 });

// 1) Set the scene: host, kernel, two containers (from previous step)
h.reveal(tl, [host, kernel], 0, { from: 'up', stagger: 0.1, duration: 0.6 });
h.reveal(tl, conts, '>0.1', { from: 'down', stagger: 0.2, duration: 0.6 });
h.reveal(tl, allPanels, '>0.2', { from: 'scale', stagger: 0.05, duration: 0.5 });
h.reveal(tl, allPids, '>0.1', { from: 'fade', stagger: 0.05, duration: 0.5 });

// 2) Container A tries to look sideways at B
h.reveal(tl, look, '>0.5', { from: 'scale', duration: 0.5 });
h.moveBy(tl, look, { dx: 14, dy: 0 }, '>0.1');

// 3) The namespace wall appears and blocks the view
h.draw(tl, wall, '>0.1', { duration: 0.8 });
h.recolor(tl, wall, 'active', '>0.1');
h.reveal(tl, nsLabel, '<', { from: 'down', duration: 0.6 });
h.recolor(tl, look, 'danger', '<');
h.hide(tl, look, '>0.3');

// 4) Each container sees only its own world
h.recolor(tl, panels[0], 'active', '>0.4');
h.recolor(tl, panels[1], 'active', '<');
h.pulse(tl, allPanels, '>0.1', { times: 1 });

// Own process list, numbered from PID 1 in each container
h.wait(tl, 0.4);
h.recolor(tl, allPids, 'new', '>');
const ring = h.highlight(tl, pids[0][0], '>0.2', { role: 'new', pad: 6 });
h.pulse(tl, [pids[0][0], pids[1][0]], '>0.2', { times: 1 });

h.wait(tl, 2);
return tl;

// Layout: Host Computer container fills canvas (x40..920, y56..496).
// Kernel row at bottom (y420, h56): 'Linux Kernel' bar x64..600 (muted), 'cgroups' box x624..896.
// Container A x64..264, Container B x480..680, both y110..382, each with App + two lib blocks.
// Gauges as thick vertical bars beside each container: A at x304 (CPU) / x376 (Memory),
// B at x720 (CPU) / x792 (Memory). Bars run y360 (empty) up to y160 (limit line).
// Limit labels above at y136, gauge names below at y368.
const tl = h.timeline();

const host = h.container({ x: 40, y: 56, w: 880, h: 440, label: 'Host Computer', role: 'neutral' });
const kernel = h.box({ x: 64, y: 420, w: 536, h: 56, label: 'Linux Kernel', role: 'muted' });
const cg = h.box({ x: 624, y: 420, w: 272, h: 56, label: 'cgroups', sub: 'resource limits', role: 'neutral' });

const names = ['Container A', 'Container B'];
const cxs = [64, 480];
const conts = [], insides = [];
for (let i = 0; i < 2; i++) {
  const c = h.container({ x: cxs[i], y: 110, w: 200, h: 272, label: names[i], role: 'neutral' });
  const iy = c.inner.y + 8;
  const app = h.box({ x: cxs[i] + 20, y: iy, w: 160, h: 56, label: 'App', role: 'neutral' });
  const l1 = h.box({ x: cxs[i] + 20, y: iy + 80, w: 160, h: 40, label: 'libs', role: 'neutral', size: 'body' });
  const l2 = h.box({ x: cxs[i] + 20, y: iy + 132, w: 160, h: 40, label: 'runtime', role: 'neutral', size: 'body' });
  conts.push(c);
  insides.push(app, l1, l2);
}

// Gauges
const gx = [[304, 376], [720, 792]];
const bottom = 360, limitY = 160;
const tracks = [], gLabels = [], limits = [], limitTexts = [];
for (let i = 0; i < 2; i++) {
  for (let j = 0; j < 2; j++) {
    const x = gx[i][j];
    tracks.push(h.line({ x, y: bottom }, { x, y: limitY - 6 }, { role: 'muted', width: 28, gap: 0 }));
    gLabels.push(h.text({ x, y: 368, text: j === 0 ? 'CPU' : 'Memory', size: 'small', anchor: 'middle' }));
    limits.push(h.line({ x: x - 22, y: limitY }, { x: x + 22, y: limitY }, { role: 'neutral', width: 3, gap: 0 }));
    limitTexts.push(h.text({ x, y: 134, text: j === 0 ? 'limit' : 'max 512 MB', size: 'small', anchor: 'middle', muted: j === 0 }));
  }
}

// Fill levels: A CPU, A Mem (rises to limit), B CPU, B Mem
const aCpu = h.line({ x: 304, y: bottom }, { x: 304, y: 270 }, { role: 'accent', width: 28, gap: 0 });
const aMem = h.line({ x: 376, y: bottom }, { x: 376, y: limitY }, { role: 'active', width: 28, gap: 0 });
const bCpu = h.line({ x: 720, y: bottom }, { x: 720, y: 290 }, { role: 'accent', width: 28, gap: 0 });
const bMem = h.line({ x: 792, y: bottom }, { x: 792, y: 280 }, { role: 'accent', width: 28, gap: 0 });

// cgroups enforces limits
const linkA = h.line({ x: 660, y: 414 }, { x: 390, y: 392 }, { role: 'muted', dashed: true, gap: 0 });
const linkB = h.line({ x: 792, y: 414 }, { x: 792, y: 392 }, { role: 'muted', dashed: true, gap: 0 });

gsap.set([host, kernel, cg, ...conts, ...insides, ...tracks, ...gLabels, ...limits, ...limitTexts], { opacity: 0 });

// 1) Scene from before
h.reveal(tl, [host, kernel], 0, { from: 'fade', stagger: 0.1 });
h.reveal(tl, conts, '>0.1', { from: 'down', stagger: 0.15 });
h.reveal(tl, insides, '<0.2', { from: 'fade', stagger: 0.04 });

// 2) cgroups and gauges appear
h.reveal(tl, cg, '>0.3', { from: 'up' });
h.recolor(tl, cg, 'active', '<');
h.reveal(tl, [...tracks, ...gLabels], '>0.1', { stagger: 0.05 });
h.reveal(tl, [...limits, ...limitTexts], '>0.1', { stagger: 0.05 });
h.draw(tl, linkA, '>0.1', { duration: 0.6 });
h.draw(tl, linkB, '<', { duration: 0.6 });

// Normal usage
h.draw(tl, aCpu, '>0.3', { duration: 0.8 });
h.draw(tl, bCpu, '<', { duration: 0.8 });
h.draw(tl, bMem, '<', { duration: 0.8 });

// 3) The one change: Container A's memory climbs to the limit
h.highlight(tl, conts[0], '>0.4', { role: 'active', pad: 6 });
h.draw(tl, aMem, '<', { duration: 2.6 });

// Stopped at the limit
h.recolor(tl, [limits[1], limitTexts[1]], 'danger', '>');
h.recolor(tl, aMem, 'danger', '<');
h.pulse(tl, [limits[1], limitTexts[1]], '>0.1', { times: 2 });
h.pulse(tl, cg, '<', { times: 1 });

// B stays steady
h.pulse(tl, [bCpu, bMem], '>0.4', { times: 1, scale: 1.03 });

h.wait(tl, 2);
return tl;

// Layout: outer 'Windows or macOS' container fills canvas (x 40..920, y 60..500).
// Left column (x 64..264): 'Docker client' code panel at y 148, note below at y 340.
// Right: 'Lightweight Linux VM' container x 336..896, y 100..480 (new colour).
//   Docker daemon box x 360..560, y 148..204.
//   Two containers y 232..384: A x 360..592, B x 640..872 (gap 48); App + libs inside each.
//   'Linux Kernel' bar x 360..872, y 408..456 (muted), under the containers.
const tl = h.timeline();

const os = h.container({ x: 40, y: 60, w: 880, h: 440, label: 'Windows or macOS', role: 'neutral' });
const vm = h.container({ x: 336, y: 100, w: 560, h: 380, label: 'Lightweight Linux VM', role: 'new' });

const client = h.code({ x: 64, y: 148, w: 200, title: 'Docker client', lines: ['$ docker run nginx'] });
const daemon = h.box({ x: 360, y: 148, w: 200, h: 56, label: 'Docker daemon', role: 'neutral', size: 'body' });

const kernel = h.box({ x: 360, y: 408, w: 512, h: 48, label: 'Linux Kernel', role: 'muted', size: 'body' });

const xs = [360, 640];
const names = ['Container 1', 'Container 2'];
const conts = [], insides = [];
for (let i = 0; i < 2; i++) {
  const x0 = xs[i];
  const c = h.container({ x: x0, y: 232, w: 232, h: 152, label: names[i], role: 'neutral' });
  const app = h.box({ x: x0 + 24, y: 274, w: 184, h: 40, label: 'App', role: 'neutral', size: 'body' });
  const libs = h.box({ x: x0 + 24, y: 326, w: 184, h: 36, label: 'libraries', role: 'neutral', size: 'small', shape: 'pill' });
  conts.push(c);
  insides.push(app, libs);
}

const cmd = h.arrow(client, daemon, { role: 'accent', fromSide: 'right', toSide: 'left' });
const note = h.note({ x: 64, y: 340, w: 240, text: 'No Linux kernel on the host, so Docker Desktop brings one.', role: 'accent' });

gsap.set([vm, client, daemon, kernel, ...conts, ...insides, note], { opacity: 0 });

// 1) Set the scene: the non-Linux computer, the client, the familiar daemon, containers and kernel
h.reveal(tl, os, 0, { from: 'up', duration: 0.6 });
h.reveal(tl, client, '>0.1', { from: 'left', duration: 0.6 });
h.reveal(tl, [daemon, kernel], '<', { from: 'fade', stagger: 0.1, duration: 0.6 });
h.reveal(tl, conts, '>0.1', { from: 'down', stagger: 0.15, duration: 0.6 });
h.reveal(tl, insides, '>0.1', { from: 'scale', stagger: 0.05, duration: 0.5 });

// 2) The one change: a hidden Linux VM appears around them
h.wait(tl, 0.4);
h.reveal(tl, vm, '>', { from: 'scale', duration: 1 });
const ring = h.highlight(tl, vm, '>0.1', { role: 'new', pad: 6 });
h.pulse(tl, kernel, '>0.2', { times: 1 });
h.hide(tl, ring, '>0.3');

// 3) Commands from the client cross into the VM's daemon
h.highlightLine(tl, client, 0, '>0.3');
h.draw(tl, cmd, '>0.2', { duration: 0.6 });
h.flow(tl, client, daemon, '>', { label: 'run', along: cmd, role: 'accent', duration: 1.2 });
h.recolor(tl, daemon, 'active', '>-0.2');
h.pulse(tl, conts, '>0.2', { times: 1 });

h.reveal(tl, note, '>0.4', { from: 'up', duration: 0.6 });
h.wait(tl, 2);
return tl;
